        time.sleep(0.08)
        self.assertEqual(404, self.server.request("GET", path)[0])
        self.assertEqual({"keys": []}, self.server.request("GET", "/v1/keys")[2])
        for ttl in (0, -1, True):
            self.assertEqual(400, self.server.request("PUT", path, {"value": 1, "ttl_seconds": ttl})[0])
        self.assertEqual(400, self.server.request("PUT", "/v1/kv/a%2Fb", {"value": 1})[0])
        self.assertEqual(405, self.server.request("POST", "/health", {})[0])
        self.assertEqual(404, self.server.request("GET", "/missing")[0])
        huge = b" " * (1024 * 1024 + 1)
        connection = http.client.HTTPConnection("127.0.0.1", self.server.port, timeout=3)
        connection.request("PUT", path, body=huge, headers={"Content-Type": "application/json"})
        response = connection.getresponse()
        self.assertEqual(413, response.status)
        response.read()
        connection.close()


if __name__ == "__main__":
    unittest.main()
# Persistent HTTP key-value service

A dependency-free Python 3.11+ JSON HTTP service with atomic on-disk persistence.

```sh
python3 server.py --host 127.0.0.1 --port 8080 --data ./data.json
```

Use port `0` to select a free port; the service prints `LISTENING <port>` as its
first stdout line. Diagnostics go to stderr.

## API

- `PUT /v1/kv/{url-encoded-key}` — body: `{"value": <JSON>, "ttl_seconds": <positive number>}` (`ttl_seconds` is optional)
- `GET /v1/kv/{url-encoded-key}`
- `DELETE /v1/kv/{url-encoded-key}`
- `GET /v1/keys`
- `GET /health`

Keys are UTF-8, non-empty, and cannot contain `/`. Request bodies are limited to
1 MiB. Entries are written with an atomic file replacement and expired entries
are removed on startup and while serving requests.

Run the self-tests with:

```sh
python3 -m unittest -v
```
