                # still been flushed and replaced atomically.
                pass
        except (OSError, TypeError, ValueError) as error:
            raise StoreError(f"cannot persist data file {self.path}: {error}") from error
        finally:
            if temporary_name is not None:
                try:
                    os.unlink(temporary_name)
                except OSError:
                    pass

    def put(self, key: str, value: Any, ttl_seconds: float | None) -> bool:
        with self.lock:
            previous = dict(self.entries)
            self._prune_locked(time.time())
            existed = key in self.entries
            expires_at = None if ttl_seconds is None else time.time() + ttl_seconds
            self.entries[key] = {"value": value, "expires_at": expires_at}
            try:
                self._persist_locked()
            except StoreError:
                self.entries = previous
                raise
            return existed

    def get(self, key: str) -> tuple[bool, Any]:
        with self.lock:
            entry = self.entries.get(key)
            if entry is None:
                return False, None
            if not self._is_live(entry, time.time()):
                del self.entries[key]
                self._persist_best_effort_locked()
                return False, None
            return True, entry["value"]

    def delete(self, key: str) -> bool:
        with self.lock:
            previous = dict(self.entries)
            self._prune_locked(time.time())
            if key not in self.entries:
                return False
            del self.entries[key]
            try:
                self._persist_locked()
            except StoreError:
                self.entries = previous
                raise
            return True

    def keys(self) -> list[str]:
        with self.lock:
            if self._prune_locked(time.time()):
                self._persist_best_effort_locked()
            return sorted(self.entries)

    def _persist_best_effort_locked(self) -> None:
        try:
            self._persist_locked()
        except StoreError as error:
            print(error, file=sys.stderr, flush=True)


class KeyValueHTTPServer(ThreadingHTTPServer):
    daemon_threads = False
    allow_reuse_address = True

    def __init__(self, address: tuple[str, int], store: PersistentStore) -> None:
        super().__init__(address, RequestHandler)
        self.store = store


class RequestHandler(BaseHTTPRequestHandler):
    server: KeyValueHTTPServer
    protocol_version = "HTTP/1.1"

    def do_GET(self) -> None:
        self._dispatch("GET")

    def do_PUT(self) -> None:
        self._dispatch("PUT")

    def do_DELETE(self) -> None:
        self._dispatch("DELETE")

    def do_POST(self) -> None:
        self._dispatch("POST")

    def do_PATCH(self) -> None:
        self._dispatch("PATCH")

    def do_HEAD(self) -> None:
        self._dispatch("HEAD")

    def do_OPTIONS(self) -> None:
        self._dispatch("OPTIONS")

    def log_message(self, format_string: str, *args: Any) -> None:
        print(f"{self.client_address[0]} - {format_string % args}", file=sys.stderr, flush=True)

    def _dispatch(self, method: str) -> None:
        try:
            parsed = urlsplit(self.path)
        except ValueError:
            self._send_error(400, "invalid URL")
            return
        if parsed.query or parsed.fragment:
            self._send_error(404, "unknown route")
            return

        if parsed.path == "/health":
            if method != "GET":
                self._method_not_allowed("GET")
            else:
                self._send_json(200, {"status": "ok"})
            return

        if parsed.path == "/v1/keys":
            if method != "GET":
                self._method_not_allowed("GET")
            else:
                self._send_json(200, {"keys": self.server.store.keys()})
            return

        prefix = "/v1/kv/"
        if parsed.path.startswith(prefix):
            raw_key = parsed.path[len(prefix):]
            try:
                key = unquote_to_bytes(raw_key).decode("utf-8", errors="strict")
            except (UnicodeDecodeError, ValueError):
                self._send_error(400, "key must be valid UTF-8")
                return
            if not key or "/" in key:
                self._send_error(400, "key must be non-empty and must not contain '/'")
                return
            if method == "GET":
                self._handle_get(key)
            elif method == "PUT":
                self._handle_put(key)
            elif method == "DELETE":
                self._handle_delete(key)
            else:
                self._method_not_allowed("GET, PUT, DELETE")
            return

        self._send_error(404, "unknown route")

    def _read_json(self) -> tuple[bool, Any]:
        if self.headers.get("Transfer-Encoding") is not None:
            self.close_connection = True
            self._send_error(400, "Transfer-Encoding is not supported")
            return False, None
        raw_length = self.headers.get("Content-Length")
        if raw_length is None:
            self._send_error(411, "Content-Length is required")
            return False, None
        try:
            length = int(raw_length, 10)
        except ValueError:
            self.close_connection = True
            self._send_error(400, "invalid Content-Length")
            return False, None
        if length < 0:
            self.close_connection = True
            self._send_error(400, "invalid Content-Length")
            return False, None
        if length > MAX_BODY_BYTES:
            self.close_connection = True
            self._send_error(413, "request body exceeds 1 MiB")
            return False, None
        body = self.rfile.read(length)
        try:
            text = body.decode("utf-8", errors="strict")
            value = json.loads(text, parse_constant=PersistentStore._reject_constant)
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError):
            self._send_error(400, "malformed JSON")
            return False, None
        return True, value

    def _handle_put(self, key: str) -> None:
        ok, body = self._read_json()
        if not ok:
            return
        if not isinstance(body, dict) or "value" not in body or set(body) - {"value", "ttl_seconds"}:
            self._send_error(400, "body must be an object containing value and optional ttl_seconds")
            return
        ttl = body.get("ttl_seconds")
        if ttl is not None and (
            isinstance(ttl, bool)
            or not isinstance(ttl, (int, float))
            or not math.isfinite(ttl)
            or ttl <= 0
        ):
            self._send_error(400, "ttl_seconds must be finite and greater than zero")
            return
        try:
            replaced = self.server.store.put(key, body["value"], ttl)
        except StoreError as error:
            print(error, file=sys.stderr, flush=True)
            self._send_error(500, "failed to persist value")
            return
        self._send_json(200 if replaced else 201, {"key": key, "value": body["value"]})

    def _handle_get(self, key: str) -> None:
        try:
            found, value = self.server.store.get(key)
        except StoreError as error:
            print(error, file=sys.stderr, flush=True)
            self._send_error(500, "failed to persist expiry cleanup")
            return
        if not found:
            self._send_error(404, "key not found")
        else:
            self._send_json(200, {"key": key, "value": value})

import http.client
import json
import os
import signal
import subprocess
import sys
import tempfile
import time
import unittest
from pathlib import Path
from urllib.parse import quote


class RunningServer:
    def __init__(self, data_path):
        self.process = subprocess.Popen(
            [sys.executable, "server.py", "--host", "127.0.0.1", "--port", "0", "--data", str(data_path)],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )
        line = self.process.stdout.readline().strip()
        if not line.startswith("LISTENING "):
            raise RuntimeError(f"server did not start: {line!r} {self.process.stderr.read()!r}")
        self.port = int(line.split()[1])

    def request(self, method, path, body=None, headers=None):
        connection = http.client.HTTPConnection("127.0.0.1", self.port, timeout=3)
        payload = None if body is None else json.dumps(body).encode()
        actual_headers = dict(headers or {})
        if payload is not None:
            actual_headers.setdefault("Content-Type", "application/json")
        connection.request(method, path, body=payload, headers=actual_headers)
        response = connection.getresponse()
        content = response.read()
        result = (response.status, dict(response.getheaders()), json.loads(content) if content else None)
        connection.close()
        return result

    def stop(self):
        if self.process.poll() is None:
            self.process.send_signal(signal.SIGTERM)
            self.process.wait(timeout=5)
        self.process.stdout.close()
        self.process.stderr.close()


class ServiceTests(unittest.TestCase):
    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory()
        self.data = Path(self.temporary.name) / "store.json"
        self.server = RunningServer(self.data)

    def tearDown(self):
        self.server.stop()
        self.temporary.cleanup()

    def test_crud_keys_and_restart(self):
        key = "a key ☃"
        path = "/v1/kv/" + quote(key, safe="")
        status, headers, body = self.server.request("PUT", path, {"value": {"x": [1, True]}})
        self.assertEqual(201, status)
        self.assertEqual("application/json", headers["Content-Type"])
        self.assertEqual({"key": key, "value": {"x": [1, True]}}, body)
        self.assertEqual(200, self.server.request("PUT", path, {"value": "new"})[0])
        self.assertEqual({"key": key, "value": "new"}, self.server.request("GET", path)[2])
        self.assertEqual({"keys": [key]}, self.server.request("GET", "/v1/keys")[2])
        self.server.stop()
        self.server = RunningServer(self.data)
        self.assertEqual({"key": key, "value": "new"}, self.server.request("GET", path)[2])
        self.assertEqual(204, self.server.request("DELETE", path)[0])
        self.assertEqual(404, self.server.request("GET", path)[0])

    def test_ttl_validation_routes_and_limit(self):
        path = "/v1/kv/short"
        self.assertEqual(201, self.server.request("PUT", path, {"value": 1, "ttl_seconds": 0.05})[0])
        time.sleep(0.08)
        self.assertEqual(404, self.server.request("GET", path)[0])
        self.assertEqual({"keys": []}, self.server.request("GET", "/v1/keys")[2])
        for ttl in (0, -1, True):
            self.assertEqual(400, self.server.request("PUT", path, {"value": 1, "ttl_seconds": ttl})[0])
        self.assertEqual(400, self.server.request("PUT", "/v1/kv/a%2Fb", {"value": 1})[0])
        self.assertEqual(405, self.server.request("POST", "/health", {})[0])
        self.assertEqual(404, self.server.request("GET", "/missing")[0])
        huge = b" " * (1024 * 1024 + 1)
        connection = http.client.HTTPConnection("127.0.0.1", self.server.port, timeout=3)
        connection.request("PUT", path, body=huge, headers={"Content-Type": "application/json"})
        response = connection.getresponse()
        self.assertEqual(413, response.status)
        response.read()
        connection.close()


if __name__ == "__main__":
    unittest.main()
# Persistent HTTP key-value service

A dependency-free Python 3.11+ JSON HTTP service with atomic on-disk persistence.

```sh
python3 server.py --host 127.0.0.1 --port 8080 --data ./data.json
```

Use port `0` to select a free port; the service prints `LISTENING <port>` as its
first stdout line. Diagnostics go to stderr.

## API

- `PUT /v1/kv/{url-encoded-key}` — body: `{"value": <JSON>, "ttl_seconds": <positive number>}` (`ttl_seconds` is optional)
- `GET /v1/kv/{url-encoded-key}`
- `DELETE /v1/kv/{url-encoded-key}`
- `GET /v1/keys`
- `GET /health`

Keys are UTF-8, non-empty, and cannot contain `/`. Request bodies are limited to
1 MiB. Entries are written with an atomic file replacement and expired entries
are removed on startup and while serving requests.

Run the self-tests with:

```sh
python3 -m unittest -v
```

